    11	function getAuthenticateErrorMessage(response: Response): TranslationPaths {
    12	    switch (response.jsonCode) {
    13	        case CONST.JSON_CODE.UNABLE_TO_RETRY:
    14	            return 'session.offlineMessageRetry';
    15	        case 401:
    16	            return 'passwordForm.error.incorrectLoginOrPassword';
    17	        case 402:
    18	            // If too few characters are passed as the password, the WAF will pass it to the API as an empty
    19	            // string, which results in a 402 error from Auth.
    20	            if (response.message === '402 Missing partnerUserSecret') {
    21	                return 'passwordForm.error.incorrectLoginOrPassword';
    22	            }
    23	            return 'passwordForm.error.twoFactorAuthenticationEnabled';
    24	        case 403:
    25	            if (response.message === 'Invalid code') {
    26	                return 'passwordForm.error.incorrect2fa';
    27	            }
    28	            return 'passwordForm.error.invalidLoginOrPassword';
    29	        case 404:
    30	            return 'passwordForm.error.unableToResetPassword';
    31	        case 405:
    32	            return 'passwordForm.error.noAccess';
    33	        case 413:
    34	            return 'passwordForm.error.accountLocked';
    35	        default:
