   111	function getEarliestErrorField<TOnyxData extends OnyxDataWithErrorFields>(onyxData: OnyxEntry<TOnyxData>, fieldName: string): Errors {
   112	    const errorsForField = onyxData?.errorFields?.[fieldName] ?? {};
   113	
