   137	/**
   138	 * Method used to attach already translated message
   139	 * @param errors - An object containing current errors in the form
   140	 * @returns Errors in the form of {timestamp: message}
   141	 */
   142	function getErrorsWithTranslationData(errors: Errors): Errors {
   143	    if (!errors) {
   144	        return {};
   145	    }
   146	
   147	    if (typeof errors === 'string') {
   148	        // eslint-disable-next-line @typescript-eslint/naming-convention
   149	        return {'0': getErrorMessageWithTranslationData(errors)};
   150	    }
   151	
   152	    return mapValues(errors, getErrorMessageWithTranslationData);
   153	}
