   155	/**
   156	 * Method used to generate error message for given inputID
   157	 * @param errors - An object containing current errors in the form
   158	 * @param message - Message to assign to the inputID errors
   159	 */
   160	function addErrorMessage(errors: Errors, inputID?: string | null, message?: string | null) {
   161	    if (!message || !inputID) {
   162	        return;
   163	    }
   164	
   165	    const errorList = errors;
   166	    const error = errorList[inputID];
   167	
   168	    if (!error) {
   169	        errorList[inputID] = message;
   170	    } else if (typeof error === 'string') {
   171	        errorList[inputID] = `${error}\n${message}`;
   172	    }
   173	}
   174	
   175	/**
   176	 * Check if the error includes a receipt.
   177	 */
   178	function isReceiptError(message: unknown): message is ReceiptError {
   179	    if (typeof message === 'string') {
   180	        return false;
   181	    }
   182	    if (Array.isArray(message)) {
   183	        return false;
   184	    }
   185	    if (Object.keys(message as Record<string, unknown>).length === 0) {
   186	        return false;
   187	    }
   188	    return ((message as Record<string, unknown>)?.error ?? '') === CONST.IOU.RECEIPT_ERROR;
   189	}
